  VALUES ?graph {
    <urn:graphragprov:unit:u_111863ccbada53d2>
    <urn:graphragprov:unit:u_a5821cb2745595a3>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
